605	    /// `commit`, tracking every new file whatever its size.
606	    ///
607	    /// Returns the new files over `snapshot.max-new-file-size`, with
608	    /// their sizes, which a plain `commit` would have left out, so
609	    /// the caller can say what the lifted limit let in. For a first
610	    /// commit of content the user asked to adopt, where a silently
611	    /// missing file is the worse outcome.
612	    pub fn commit_any_size(&mut self, desc: &str) -> Result<Vec<(String, u64)>> {
613	        let too_large = self.snapshot_with(None)?;
614	        if !too_large.is_empty() {
615	            self.snapshot_with(Some(u64::MAX))?;
616	        }
617	        self.commit(desc)?;
618	        Ok(too_large)
619	    }
