621	    /// Snapshot the working copy, then update the wc commit's
622	    /// description and start a new empty change on top (`jj commit`).
623	    pub fn commit(&mut self, desc: &str) -> Result<()> {
624	        self.snapshot()?;
625	        let wc_commit = self.wc_commit()?;
626	        let name = self.workspace.workspace_name().to_owned();
627	        let mut tx = self.start_tx();
628	        let new_commit = tx
629	            .repo_mut()
630	            .rewrite_commit(&wc_commit)
631	            .set_description(complete_newline(desc))
632	            .write()
633	            .block_on()?;
634	        let new_wc_commit = tx
635	            .repo_mut()
636	            .new_commit(vec![new_commit.id().clone()], wc_commit.tree())
637	            .write()
638	            .block_on()?;
639	        tx.repo_mut().edit(name, &new_wc_commit).block_on()?;
640	        self.finish_tx(tx, &format!("commit {}", wc_commit.id().hex()))
641	    }
