643	    /// Snapshot, then rewrite `rev`'s description and rebase its
644	    /// descendants (`jj describe -r <rev> -m <desc>`).
645	    pub fn describe(&mut self, rev: &str, desc: &str) -> Result<()> {
646	        self.snapshot()?;
647	        let commit = self.one_commit(rev)?;
648	        let desc = complete_newline(desc);
649	        if commit.description() == desc {
650	            return Ok(());
651	        }
652	        let mut tx = self.start_tx();
653	        tx.repo_mut()
654	            .rewrite_commit(&commit)
655	            .set_description(desc)
656	            .write()
657	            .block_on()?;
658	        tx.repo_mut().rebase_descendants().block_on()?;
659	        self.finish_tx(tx, &format!("describe commit {}", commit.id().hex()))
660	    }
661	
662	    /// Snapshot, then start a fresh empty working-copy commit on
663	    /// top of `rev` (`jj new <rev>`). The old `@` is auto-abandoned
664	    /// when discardable (empty, undescribed, unreferenced, a head),
665	    /// matching the CLI, via `MutableRepo::check_out`'s edit path.
666	    pub fn new_on(&mut self, rev: &str) -> Result<()> {
667	        self.snapshot()?;
668	        let target = self.one_commit(rev)?;
669	        let name = self.workspace.workspace_name().to_owned();
670	        let mut tx = self.start_tx();
671	        tx.repo_mut().check_out(name, &target).block_on()?;
672	        self.finish_tx(tx, &format!("new empty commit on {}", target.id().hex()))
673	    }
674	
675	    /// Snapshot, then rebase the branch of `source` onto `dest`
676	    /// (`jj rebase -b <source> -d <dest>`): the roots of
677	    /// `dest..source` are rebased onto `dest`, and `finish_tx`'s
678	    /// `rebase_descendants` carries their descendants along, the
679	    /// working-copy pointer included. Conflicts are written, not
680	    /// refused: callers keep their post-rebase conflict checks.
681	    pub fn rebase_branch(&mut self, source: &str, dest: &str) -> Result<()> {
682	        self.snapshot()?;
683	        let dest_commit = self.one_commit(dest)?;
684	        let root_ids = crate::common::resolve_revset(
685	            &self.workspace,
686	            &self.repo,
687	            &format!("roots({dest}..{source})"),
688	        )?;
689	        if root_ids.is_empty() {
690	            debug!("rebase_branch: '{source}' is already on '{dest}', nothing to do");
691	            return Ok(());
692	        }
693	        let mut tx = self.start_tx();
694	        for id in &root_ids {
695	            let commit = tx.repo().store().get_commit(id)?;
696	            jj_lib::rewrite::rebase_commit(tx.repo_mut(), commit, vec![dest_commit.id().clone()])
697	                .block_on()?;
698	        }
699	        self.finish_tx(
700	            tx,
701	            &format!(
702	                "rebase {} commits onto {}",
703	                root_ids.len(),
704	                dest_commit.id().hex()
705	            ),
706	        )
707	    }
708	
709	    /// Snapshot, then restore the repo to the operation named by
710	    /// `op_str`, id prefixes included (`jj op restore <op>`): a new
711	    /// operation whose view is the target's, the working copy
712	    /// updated to the restored wc commit.
713	    ///
714	    /// Deviation from the CLI: no `--what` portioning. The full
715	    /// target view is restored, which is the CLI's default. Like
716	    /// the CLI, `git_refs` / `git_head` stay at their *current*
717	    /// values: they track what the colocated git side actually
718	    /// holds, and restoring the old records would make the next
719	    /// git import resurrect exactly the commits being undone.
720	    pub fn restore_op(&mut self, op_str: &str) -> Result<()> {
721	        self.snapshot()?;
722	        let target_op = jj_lib::op_walk::resolve_op_for_load(self.workspace.repo_loader(), op_str)
723	            .block_on()?;
724	        let mut new_view = target_op.view().block_on()?.store_view().clone();
725	        let current_view = self.repo.view().store_view();
726	        new_view.git_refs = current_view.git_refs.clone();
727	        new_view.git_heads = current_view.git_heads.clone();
728	        let mut tx = self.start_tx();
729	        tx.repo_mut().set_view(new_view);
730	        self.finish_tx(
731	            tx,
732	            &format!("restore to operation {}", target_op.id().hex()),
733	        )
