    let target_commit = self.one_commit(target)?;
    let selection = CommitWithSelection {
        commit: source_commit.clone(),
        selected_tree: source_commit.tree(),
        parent_tree: source_commit.parent_tree(self.repo.as_ref()).block_on()?,
