    /// A fixture repo with `snapshot.max-new-file-size` at 1 KiB in
    /// its own jj config, which outranks the user's, and a new
    /// 2 KiB `big.bin` beside a small file in its working copy.
    fn repo_with_a_file_over_the_limit(repo: &Path) {
        use crate::test_helpers::jj_ok;
        jj_ok(
            repo,
            &["config", "set", "--repo", "snapshot.max-new-file-size", "1KiB"],
        );
        std::fs::write(repo.join("big.bin"), vec![0u8; 2048]).expect("write big.bin");
        std::fs::write(repo.join("small.txt"), "fits").expect("write small.txt");
    }

    #[test]
    fn snapshot_fails_on_a_new_file_over_the_limit() {
        use crate::test_helpers::{Fixture, jj_ok};
        let fx = Fixture::new("snapshot-too-large");
        repo_with_a_file_over_the_limit(&fx.work);
        let mut ses = RepoSession::open(&fx.work).expect("open the work repo");

        let err = ses.snapshot().expect_err("a refused file fails the snapshot");
        let too_large = err.downcast_ref::<FilesTooLarge>().expect("a FilesTooLarge");
        assert_eq!(too_large.files, vec![("big.bin".to_string(), 2048)]);
        assert_eq!(too_large.limit, 1024);
        assert!(!too_large.agent_repo);
        let msg = err.to_string();
        assert!(msg.contains("  big.bin: 2.0KiB"), "{msg}");
        assert!(msg.contains("snapshot.max-new-file-size 2048"), "{msg}");
        assert!(!msg.contains("snapshot.max-new-file-size 0"), "{msg}");

        // The file under the limit was snapshotted, and the refused
        // one is refused again by the next snapshot.
        let listed = jj_ok(&fx.work, &["file", "list", "-r", "@"]);
        assert!(listed.contains("small.txt"), "{listed}");
        assert!(!listed.contains("big.bin"), "{listed}");
        assert!(ses.snapshot().is_err(), "the next snapshot fails again");
    }

    #[test]
    fn snapshot_in_an_agent_repo_names_no_limit_as_a_remedy() {
        use crate::test_helpers::Fixture;
        let fx = Fixture::new("snapshot-too-large-agent");
        repo_with_a_file_over_the_limit(&fx.bot);
        let mut ses = RepoSession::open(&fx.bot).expect("open the agent-repo");

        let err = ses.snapshot().expect_err("a refused file fails the snapshot");
        let too_large = err.downcast_ref::<FilesTooLarge>().expect("a FilesTooLarge");
        assert!(too_large.agent_repo);
        let msg = err.to_string();
        assert!(msg.contains("snapshot.max-new-file-size 0"), "{msg}");
    }

    #[test]
    fn commit_any_size_still_takes_a_file_over_the_limit() {
        use crate::test_helpers::{Fixture, jj_ok};
        let fx = Fixture::new("snapshot-any-size");
        repo_with_a_file_over_the_limit(&fx.work);
        let mut ses = RepoSession::open(&fx.work).expect("open the work repo");

        let let_in = ses.commit_any_size("adopt").expect("commit_any_size succeeds");
        assert_eq!(let_in, vec![("big.bin".to_string(), 2048)]);
        let listed = jj_ok(&fx.work, &["file", "list", "-r", "@-"]);
        assert!(listed.contains("big.bin"), "{listed}");
    }
}
